SELECT SEC_NAME AS `证券简称`, COMB_SYMBOL AS `证券代码`, ROUND(SUM(MARKET_VALUE) / 100000000, 1) AS `总持股市值(亿)`, COUNT(DISTINCT FUND_HCODE) AS `持有基金数量` FROM FUND_PORTFOLIO_DETAIL WHERE REPORT_DATE = '2026-06-30' AND FUND_HOLDING_SOURCE_ID = 1 AND MARKET_VALUE IS NOT NULL AND HISVALID = 1 GROUP BY SEC_NAME, COMB_SYMBOL ORDER BY `总持股市值(亿)` DESC LIMIT 1;
